package edu.pe.cibertec.saibm.inventario.infrastructure.persistence; import java.util.*; import org.springframework.stereotype.Component; import com.fasterxml.jackson.databind.ObjectMapper; import edu.pe.cibertec.saibm.inventario.application.port.out.InventoryStorePort; import edu.pe.cibertec.saibm.inventario.domain.event.InventoryEvent; import edu.pe.cibertec.saibm.inventario.domain.model.*; @Component public class InventoryJpaAdapter implements InventoryStorePort {private final StockJpaRepository stocks;private final HoldJpaRepository holds;private final MovementJpaRepository movements;private final OutboxJpaRepository outbox;private final ObjectMapper mapper;public InventoryJpaAdapter(StockJpaRepository s,HoldJpaRepository h,MovementJpaRepository m,OutboxJpaRepository o,ObjectMapper x){stocks=s;holds=h;movements=m;outbox=o;mapper=x;}public Optional<Stock> stockForUpdate(String id){return stocks.findForUpdate(id).map(StockJpaEntity::domain);}public Optional<Hold> holdForUpdate(String k){return holds.findForUpdate(k).map(HoldJpaEntity::domain);}public boolean insert(Hold h){return holds.insertIfAbsent(h.id(),h.operationKey(),h.bookId(),h.quantity(),h.expiresAt(),h.requestHash(),h.state().name())==1;}public void save(Stock s){stocks.save(new StockJpaEntity(s));}public void save(Hold h){holds.save(new HoldJpaEntity(h));}public void movement(InventoryMovement m){movements.save(new MovementJpaEntity(m));}public void outbox(InventoryEvent e){try{outbox.save(new OutboxJpaEntity(e,mapper.writeValueAsString(e)));}catch(Exception x){throw new IllegalStateException("Cannot serialize inventory event",x);}}}
